    p->Start = (CTexPtr*)std::malloc(3 * sizeof(CTexPtr)); p->Finish = p->Start + 3; p->End = p->Finish;
    p->Start[0].Object = &a; p->Start[1].Object = &b; p->Start[2].Object = 0;
